/* @component: .f-number */
document.addEventListener('click', function(e) {
  let btnDec = e.target.closest('.num-btn--dec');
  if (btnDec) {
    let input = btnDec.parentElement.querySelector('input');
    if (input && input.stepDown) input.stepDown();
    return;
  }

  let btnInc = e.target.closest('.num-btn--inc');
  if (btnInc) {
    let input = btnInc.parentElement.querySelector('input');
    if (input && input.stepUp) input.stepUp();
    return;
  }
});
